## Building a Game from Scratch

### The Game Loop

```xiom
pub type Game = {
  running: Bool;
  window: Window;
  world: World;
  renderer: Renderer;
  delta_time: Float64;
}

impl Game {
  fn run(self: &mut Game) {
    while self.running && !self.window.should_close() {
      let frame_start = time::now();

      self.handle_input();
      self.update(self.delta_time);
      self.render();

      self.window.swap_buffers();
      glfw::poll_events();

      self.delta_time = time::now() - frame_start;
    }
  }
}
```

### Entity Component System (ECS)

```xiom
// Components are plain data
pub type Position = { x: Float64; y: Float64; }
pub type Velocity = { dx: Float64; dy: Float64; }
pub type Sprite = { texture_id: Int; width: Float64; height: Float64; }
pub type Health = { current: Int; max: Int; }

// Systems process components
fn movement_system(world: &mut World) {
  for (pos, vel) in world.query::<(&mut Position, &Velocity)>() {
    pos.x = pos.x + vel.dx * delta_time;
    pos.y = pos.y + vel.dy * delta_time;
  }
}

fn render_system(world: &World, renderer: &Renderer) {
  for (pos, sprite) in world.query::<(&Position, &Sprite)>() {
    renderer.draw_sprite(sprite.texture_id, pos.x, pos.y, sprite.width, sprite.height);
  }
}

fn health_system(world: &mut World) {
  for (_, health) in world.query::<(&(), &Health)>() {
    if health.current <= 0 {
      // Entity dies — remove it from world
    }
  }
}

// Spawn entities
fn spawn_player(world: &mut World, x: Float64, y: Float64) {
  world.spawn()
    .with(Position{ x: x, y: y })
    .with(Velocity{ dx: 0.0, dy: 0.0 })
    .with(Sprite{ texture_id: 0, width: 32.0, height: 32.0 })
    .with(Health{ current: 100, max: 100 });
}
```

### Input Handling

```xiom
fn input_system(world: &mut World, input: &Input) {
  let player = world.get_entity("player")?;
  let mut vel = world.get_mut::<Velocity>(player)?;

  vel.dx = 0.0;
  vel.dy = 0.0;

  if input.is_key_held(Key::A) { vel.dx = vel.dx - 300.0; }
  if input.is_key_held(Key::D) { vel.dx = vel.dx + 300.0; }
  if input.is_key_held(Key::W) { vel.dy = vel.dy - 300.0; }
  if input.is_key_held(Key::S) { vel.dy = vel.dy + 300.0; }

  // Normalize diagonal movement
  if vel.dx != 0.0 && vel.dy != 0.0 {
    let mag = (vel.dx * vel.dx + vel.dy * vel.dy).sqrt();
    vel.dx = vel.dx / mag * 300.0;
    vel.dy = vel.dy / mag * 300.0;
  }
}
```

### Asset Pipeline

```xiom
pub type AssetManager = {
  textures: HashMap[Str, Texture];
  sounds: HashMap[Str, Sound];
  shaders: HashMap[Str, Shader];
}

impl AssetManager {
  fn load_texture(self: &mut AssetManager, name: &Str, path: &Str) {
    let data = fs::read_bytes(path)?;
    let texture = Texture::from_png(&data)?;
    self.textures.insert(name, texture);
  }

  fn get_texture(self: &AssetManager, name: &Str) -> &Texture {
    return self.textures.get(name).unwrap();
  }
}
```

### Physics (Simple)

```xiom
fn collision_system(world: &mut World) {
  let entities = world.query::<(&Position, &Collider)>().collect();
  for i in 0..entities.len() {
    for j in (i + 1)..entities.len() {
      if check_collision(entities[i], entities[j]) {
        resolve_collision(world, entities[i].id, entities[j].id);
      }
    }
  }
}
